/**
 * Rewrites only the seat counter from the members table. Joins and removals
 * use this rather than a delta so the counter cannot drift from the list.
 */
export async function recountSeats(orgId: OrgId): Promise<OrganizationUsage> {
  await getUsage(orgId);

  const row = getDb()
    .update(organizationUsage)
    .set({
      seatsUsed: countSeats(orgId),
      measuredAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizationUsage.orgId, orgId))
    .returning()
    .get();

  return toUsage(row);
}

