import { defineConfig } from "vitest/config";
export default defineConfig({
  resolve: { alias: { "@": "$P/src" } },
  server: { fs: { allow: ["/"] } },
  test: { environment: "node", root: "/tmp/scr", include: ["/tmp/scr/*.test.ts"] },
});
EOF
cat > /tmp/scr/s.test.ts <<EOF
import { beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/rate-limit", async () => (await import("$P/tests/server/_support/doubles/misc")).rateLimitModule);
import { registerEventHandlers } from "@/server/services/event-registry";
import * as inv from "@/server/services/invitation-service";
import * as ms from "@/server/services/member-service";
import * as memberRepo from "@/server/repositories/member-repository";
import * as invRepo from "@/server/repositories/invitation-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { hashToken } from "@/lib/hash";
import { createTenant, useTemporaryDatabase } from "$P/tests/server/_support/fixtures";

beforeAll(async () => { await useTemporaryDatabase(); registerEventHandlers(); });

it("flows", async () => {
  const t = await createTenant("scr", "starter");
  await usageRepo.recomputeUsage(t.org.id);
  const vm = (await memberRepo.findMember(t.org.id, t.userIds.viewer))!;
  await ms.removeMember(t.actors.owner, { orgId: t.org.id, memberId: vm.id });
  expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(3);
  await expect(inv.inviteMember(t.actors.admin, { orgId: t.org.id, email: "ADMIN@scr.test", role: "member" })).rejects.toThrow(/member/);
  const i1 = await inv.inviteMember(t.actors.admin, { orgId: t.org.id, email: "viewer@scr.test", role: "admin" });
  await expect(inv.inviteMember(t.actors.admin, { orgId: t.org.id, email: "Viewer@scr.test", role: "member" })).rejects.toThrow(/pending/);
  await expect(inv.inviteMembers(t.actors.admin, { orgId: t.org.id, invites: [{email:"x@a.test",role:"member"},{email:"X@a.test",role:"member"}] })).rejects.toThrow();
  expect(await invRepo.countPendingInvitations(t.org.id)).toBe(1);
  const days = (Date.parse(i1.expiresAt) - Date.now()) / 86400000;
  expect(Math.round(days)).toBe(14);
  // replace token hash for accept
  const tok = "z".repeat(40);
  const i2 = await inv.resendInvitation(t.actors.owner, i1.id);
  expect(i2.role).toBe("admin");
  expect(await invRepo.countPendingInvitations(t.org.id)).toBe(1);
  const { getDb, invitations } = await import("@/server/db");
  const { eq } = await import("drizzle-orm");
  getDb().update(invitations).set({ tokenHash: hashToken(tok) }).where(eq(invitations.id, i2.id)).run();
  await expect(inv.acceptInvitation(t.userIds.member, { token: tok })).rejects.toThrow(/different/);
  const m = await inv.acceptInvitation(t.userIds.viewer, { token: tok });
  expect(m.id).toBe(vm.id); expect(m.role).toBe("admin"); expect(m.invitedBy).toBe(t.userIds.owner);
  expect(await ms.resolveActor(t.userIds.viewer, t.org.id)).not.toBeNull();
  expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(4);
  await expect(inv.acceptInvitation(t.userIds.viewer, { token: tok })).rejects.toThrow(/accepted/);
  // expired resend
  const e = await invRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "late@x.test", role: "viewer", expiresInDays: -1 }, t.userIds.admin, hashToken("q".repeat(40)));
  expect(await invRepo.countPendingInvitations(t.org.id)).toBe(0);
  const r = await inv.resendInvitation(t.actors.admin, e.id);
  expect(r.role).toBe("viewer");
});
EOF
npx vitest run --config /tmp/scr/vitest.config.ts 2>&1 | grep -v "npm warn" | tail -30

